def transform(grid):
    """Extend each non-background color pair that touches diagonally."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = max(set(v for row in grid for v in row), key=lambda c: sum(row.count(c) for row in grid))
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    # Extend this diagonal through the two seed cells to both edges.
                    sr, sc = r, c
                    while 0 <= sr - dr < h and 0 <= sc - dc < w:
                        sr -= dr
                        sc -= dc
                    while 0 <= sr < h and 0 <= sc < w:
                        out[sr][sc] = color
                        sr += dr
                        sc += dc
    return out
